// Get raw AI output (adjust field if needed)
const rawText = ($json.text || $json.output || "").toString();

// Split message and status
const statusMatch = rawText.match(/Lead status:\s*(Hot|Warm|Cold)/i);

const leadStatus = statusMatch ? statusMatch[1] : "Unknown";

// Remove the "Lead status" line from message
const message = rawText
  .replace(/Lead status:\s*(Hot|Warm|Cold)/i, "")
  .replace(/\n+/g, " ")
  .trim();

return [
  {
    json: {
      message,      // SMS reply text
      leadStatus    // Hot / Warm / Cold
    }
  }
];
